"""Demo 1: The logical seed and the collapse of the Liar.

Exhaustively confirms that no proposition equals its own negation, and that a
finite two-valued language with honest internal negation contains no Liar
sentence (a sentence true exactly when its own negation is true).
"""
from __future__ import annotations
from typing import List, Optional


def no_self_negation() -> bool:
    return all((p == (not p)) is False for p in (False, True))


class Language:
    def __init__(self, truth: List[bool], neg: List[int]) -> None:
        self.truth, self.neg, self.n = truth, neg, len(truth)

    def honest(self) -> bool:
        return all(self.truth[self.neg[s]] == (not self.truth[s])
                   for s in range(self.n))

    def find_liar(self) -> Optional[int]:
        for d in range(self.n):
            if self.truth[d] == self.truth[self.neg[d]]:
                return d
        return None


def main() -> None:
    assert no_self_negation()
    lang = Language(truth=[True, False], neg=[1, 0])
    assert lang.honest()
    assert lang.find_liar() is None
    print("Seed holds; honest language has no Liar sentence.")


if __name__ == "__main__":
    main()

"""Demo 2: No universal semantic fixed-point operator.

Enumerates every self-map f on a finite honest language and shows that while
individual fixed points abound, no single language provides a fixed point for
EVERY f -- the obstruction being precisely f = negation.
"""
from __future__ import annotations
from itertools import product
from typing import List, Optional


class Language:
    def __init__(self, truth: List[bool], neg: List[int]) -> None:
        self.truth, self.neg, self.n = truth, neg, len(truth)

    def fixed_point(self, f: List[int]) -> Optional[int]:
        for d in range(self.n):
            if self.truth[d] == self.truth[f[d]]:
                return d
        return None


def main() -> None:
    lang = Language(truth=[True, False], neg=[1, 0])
    universal = all(lang.fixed_point(list(f)) is not None
                    for f in product(range(lang.n), repeat=lang.n))
    assert not universal
    assert lang.fixed_point(lang.neg) is None
    print("No universal fixed-point operator; negation is the obstruction.")


if __name__ == "__main__":
    main()

"""Demo 3: Tarski undefinability and the true-but-unprovable Goedel sentence.

Part A verifies on the two-element boolean model that honest negation and a
self-referential diagonal sentence are jointly satisfiable, yet no disquotational
internal truth predicate can be added.  Part B exhibits a finite sound proof
system whose Goedel sentence is true but unprovable, so the system is incomplete.
"""
from __future__ import annotations
from itertools import product
from typing import List


def tarski_culprit() -> None:
    booleans = (False, True)
    neg = lambda b: not b
    t_bad = lambda b: False
    assert all(neg(b) == (not b) for b in booleans)          # honest
    assert True == neg(t_bad(True))                          # diagonal at L=True
    assert not all(t_bad(b) == b for b in booleans)          # disquotation fails
    # No disquotational T is consistent with the diagonal L == not L.
    for tt, tf in product(booleans, repeat=2):
        T = lambda b, tt=tt, tf=tf: tt if b else tf
        if all(T(b) == b for b in booleans):
            assert not any(b == neg(T(b)) and b != (not b) for b in booleans)


class ProofSystem:
    def __init__(self, truth: List[bool], prov: List[bool], neg: List[int],
                 godel: int) -> None:
        self.truth, self.prov, self.neg, self.godel = truth, prov, neg, godel
        self.n = len(truth)

    def sound(self) -> bool:
        return all((not self.prov[s]) or self.truth[s] for s in range(self.n))

    def godel_fixed_point(self) -> bool:
        g = self.godel
        return self.truth[g] == (not self.prov[g])

    def complete(self) -> bool:
        return all((not self.truth[s]) or self.prov[s] for s in range(self.n))


def incompleteness() -> None:
    ps = ProofSystem(truth=[True, False], prov=[False, False], neg=[1, 0], godel=0)
    assert ps.sound() and ps.godel_fixed_point()
    assert ps.truth[0] and not ps.prov[0]
    assert not ps.complete()


def main() -> None:
    tarski_culprit()
    incompleteness()
    print("Tarski impossibility and Goedel incompleteness both confirmed.")


if __name__ == "__main__":
    main()
